WITH valid_shipments AS (SELECT * FROM shipments WHERE MONTH(shipped_date) IN (1, 8, 11)), ShipmentsStats AS (SELECT QUARTER(delivered_date) AS delivered_quarter, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, ROUND((100 * SUM(CASE WHEN carrier = 'FedEx' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_fedex FROM valid_shipments GROUP BY QUARTER(delivered_date), CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM ShipmentsStats WHERE pct_fedex > 37 ORDER BY delivered_quarter, shipped_cohort LIMIT 5
